(()=>{localStorage.removeItem('abuadLifeSocial');const target='https://abuad-life-api.onrender.com/signup.html?mode=login';const raw=localStorage.getItem('abuad-life-v1');if(!raw){location.replace(target);return}document.getElementById('backup').onclick=()=>{const blob=new Blob([raw],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Abuad-Life-character.json';a.click();URL.revokeObjectURL(url)};document.getElementById('continue').href=target;})();
